css:
.psn-sim-container {
    padding: 28px;
    background: linear-gradient(160deg, #0f1729 0%, #1a1f3a 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #e8eaf2;
}

.psn-sim-container .psn-sim-header {
    background: linear-gradient(135deg, rgba(245,158,11,0.10), rgba(217,119,6,0.03));
    border-left: 4px solid #f59e0b;
    border-radius: 4px;
    padding: 28px 32px;
    margin-bottom: 24px;
    box-shadow: inset 0 0 60px rgba(245,158,11,0.04);
}
.psn-sim-container .psn-sim-header h1 {
    color: #fbbf24;
    font-size: 1.75rem;
    font-weight: 700;
    letter-spacing: 0.04em;
    margin: 0 0 8px 0;
}
.psn-sim-container .psn-sim-subtitle {
    color: #cbd5e1;
    font-size: 0.95rem;
    margin: 0;
    font-style: italic;
    letter-spacing: 0.01em;
}

.psn-sim-container .psn-sim-period-counter {
    color: #fbbf24;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.18em;
    margin: 0 0 22px 4px;
    font-weight: 700;
}
.psn-sim-container .psn-sim-period-counter span {
    margin-right: 4px;
}

.psn-sim-container .psn-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 16px;
    margin-bottom: 28px;
}
.psn-sim-container .psn-sim-status-card {
    background: rgba(30, 41, 70, 0.55);
    border: 1px solid #2d3a5e;
    border-radius: 10px;
    padding: 22px 20px;
    transition: transform 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease;
    position: relative;
    overflow: hidden;
}
.psn-sim-container .psn-sim-status-card:hover {
    border-color: #f59e0b;
    transform: translateY(-2px);
    box-shadow: 0 8px 24px rgba(0,0,0,0.3);
}
.psn-sim-container .psn-sim-status-card-primary {
    background: linear-gradient(135deg, rgba(245,158,11,0.18), rgba(217,119,6,0.05));
    border-color: #f59e0b;
    box-shadow: 0 0 24px rgba(245,158,11,0.12);
}
.psn-sim-container .psn-sim-status-card-primary::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 2px;
    background: linear-gradient(90deg, #f59e0b, #fbbf24);
}
.psn-sim-container .psn-sim-card-label {
    color: #94a3b8;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    margin-bottom: 12px;
    font-weight: 700;
}
.psn-sim-container .psn-sim-card-value {
    font-size: 2.4rem;
    font-weight: 800;
    color: #f8fafc;
    line-height: 1;
    letter-spacing: -0.02em;
}
.psn-sim-container .psn-sim-status-card-primary .psn-sim-card-value {
    color: #fbbf24;
}

.psn-sim-container .psn-sim-briefing {
    background: rgba(30, 41, 70, 0.45);
    border: 1px solid #2d3a5e;
    border-left: 3px solid #fbbf24;
    border-radius: 8px;
    padding: 22px 26px;
    margin-bottom: 24px;
}
.psn-sim-container .psn-sim-briefing h3 {
    color: #fbbf24;
    font-size: 1.05rem;
    margin: 0 0 12px 0;
    font-weight: 700;
    letter-spacing: 0.02em;
}
.psn-sim-container .psn-sim-briefing-text {
    color: #cbd5e1;
    font-size: 0.95rem;
    line-height: 1.65;
}

.psn-sim-container .psn-sim-controls {
    background: rgba(15, 23, 41, 0.7);
    border: 1px solid #2d3a5e;
    border-radius: 10px;
    padding: 28px;
    margin-bottom: 24px;
}
.psn-sim-container .psn-sim-controls h3 {
    color: #f8fafc;
    font-size: 1.05rem;
    margin: 0 0 20px 0;
    font-weight: 700;
    letter-spacing: 0.02em;
}
.psn-sim-container .psn-sim-round-block {
    display: grid;
    gap: 16px;
}
.psn-sim-container .psn-sim-form-row {
    display: flex;
    flex-direction: column;
    gap: 6px;
}
.psn-sim-container .psn-sim-form-row label {
    color: #cbd5e1;
    font-size: 0.85rem;
    font-weight: 600;
    letter-spacing: 0.02em;
}
.psn-sim-container .psn-sim-controls select,
.psn-sim-container .psn-sim-controls input[type="number"],
.psn-sim-container .psn-sim-controls input[type="text"] {
    background: #0f1729;
    border: 1px solid #2d3a5e;
    color: #e8eaf2;
    border-radius: 6px;
    padding: 10px 12px;
    width: 100%;
    font-size: 0.95rem;
    font-family: inherit;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.psn-sim-container .psn-sim-controls select:focus,
.psn-sim-container .psn-sim-controls input:focus {
    outline: none;
    border-color: #f59e0b;
    box-shadow: 0 0 0 3px rgba(245,158,11,0.18);
}
.psn-sim-container .psn-sim-controls select option {
    background: #1a1f3a;
    color: #e8eaf2;
}

.psn-sim-container .psn-sim-button-row {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-top: 22px;
    flex-wrap: wrap;
}
.psn-sim-container .psn-sim-button-row .btn-primary,
.psn-sim-container .psn-sim-button-row .btn-outline-secondary {
    border-radius: 6px;
    font-weight: 700;
    letter-spacing: 0.02em;
}
.psn-sim-container .psn-sim-button-row .btn-primary {
    background: #f59e0b;
    border-color: #f59e0b;
    color: #0f1729;
    padding: 10px 22px;
    font-size: 0.95rem;
}
.psn-sim-container .psn-sim-button-row .btn-primary:hover {
    background: #fbbf24;
    border-color: #fbbf24;
    color: #0f1729;
}
.psn-sim-container .psn-sim-button-row .btn-outline-secondary {
    background: transparent;
    border: 1px solid #475569;
    color: #cbd5e1;
    padding: 8px 16px;
    font-size: 0.85rem;
}
.psn-sim-container .psn-sim-button-row .btn-outline-secondary:hover {
    border-color: #94a3b8;
    color: #f1f5f9;
    background: rgba(148,163,184,0.05);
}

.psn-sim-container .psn-sim-feedback {
    background: rgba(30, 41, 70, 0.45);
    border: 1px solid #2d3a5e;
    border-left: 3px solid #34d399;
    border-radius: 8px;
    padding: 22px 26px;
    margin-bottom: 24px;
}
.psn-sim-container .psn-sim-feedback h3 {
    color: #34d399;
    font-size: 1.05rem;
    margin: 0 0 12px 0;
    font-weight: 700;
    letter-spacing: 0.02em;
}
.psn-sim-container .psn-sim-feedback-text {
    color: #e8eaf2;
    font-size: 0.95rem;
    line-height: 1.75;
}
.psn-sim-container .psn-sim-feedback-text strong {
    color: #fbbf24;
    letter-spacing: 0.02em;
}

.psn-sim-container .psn-sim-history {
    background: rgba(15, 23, 41, 0.7);
    border: 1px solid #2d3a5e;
    border-radius: 10px;
    padding: 22px 26px;
    margin-bottom: 24px;
}
.psn-sim-container .psn-sim-history h3 {
    color: #f8fafc;
    font-size: 1.05rem;
    margin: 0 0 16px 0;
    font-weight: 700;
}
.psn-sim-container .psn-sim-history table {
    color: #e8eaf2;
    background: transparent;
    width: 100%;
    margin-bottom: 0;
}
.psn-sim-container .psn-sim-history table th {
    color: #94a3b8;
    border-bottom: 1px solid #2d3a5e;
    border-top: 0;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.1em;
    font-weight: 700;
    padding: 10px 8px;
}
.psn-sim-container .psn-sim-history table td {
    border-top: 1px solid #1f2a47;
    padding: 10px 8px;
    font-size: 0.9rem;
}
.psn-sim-container .psn-sim-history table tbody tr:hover {
    background: rgba(245,158,11,0.04);
}

.psn-sim-container .psn-sim-chart-wrap {
    background: rgba(15, 23, 41, 0.7);
    border: 1px solid #2d3a5e;
    border-radius: 10px;
    padding: 22px;
    height: 340px;
    margin-bottom: 12px;
}

@media (max-width: 768px) {
    .psn-sim-container { padding: 16px; }
    .psn-sim-container .psn-sim-header { padding: 20px; }
    .psn-sim-container .psn-sim-header h1 { font-size: 1.3rem; }
    .psn-sim-container .psn-sim-card-value { font-size: 1.7rem; }
    .psn-sim-container .psn-sim-status-cards { grid-template-columns: 1fr 1fr; }
    .psn-sim-container .psn-sim-controls { padding: 18px; }
    .psn-sim-container .psn-sim-chart-wrap { height: 280px; }
}


/* --- EQIL 2026-08-07: accessibility + end-of-run debrief -------------------- */
.psn-sim-container :focus-visible,
.psn-sim-container select:focus-visible,
.psn-sim-container button:focus-visible {
    outline: 3px solid #1d3557;
    outline-offset: 2px;
    border-radius: 3px;
}
@media (prefers-reduced-motion: reduce) {
    .psn-sim-container *,
    .psn-sim-container *::before,
    .psn-sim-container *::after {
        animation-duration: 0.001ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.001ms !important;
        scroll-behavior: auto !important;
    }
}
.psn-sim-debrief {
    background: #ffffff;
    border: 1px solid #d6d9e0;
    border-left: 4px solid #1d3557;
    border-radius: 6px;
    padding: 20px 24px;
    margin-bottom: 22px;
}
.psn-sim-debrief h3 { margin: 0 0 4px; font-size: 1.1rem; color: #1d3557; }
.psn-sim-debrief h4 { margin: 16px 0 6px; font-size: 0.95rem; color: #1d3557; }
.psn-sim-debrief-score { font-size: 2rem; font-weight: 700; line-height: 1.1; color: #1d3557; }
.psn-sim-debrief-verdict { font-weight: 600; margin: 2px 0 14px; color: #45526b; }
.psn-sim-debrief-table { width: 100%; border-collapse: collapse; }
.psn-sim-debrief-table th,
.psn-sim-debrief-table td {
    text-align: left; padding: 6px 8px; border-bottom: 1px solid #eef0f4; font-size: 0.92rem;
}
.psn-sim-debrief-table th { font-weight: 500; width: 58%; color: #5a647a; }
.psn-sim-debrief-table td { font-weight: 600; color: #1d3557; }
.psn-sim-debrief ul { margin: 8px 0 0 18px; padding: 0; }
.psn-sim-debrief li { margin-bottom: 6px; font-size: 0.92rem; color: #45526b; }

