        getChartData(state) {
            var ds = (state && state.domainState) || {};
            var readiness = ds.readinessHistory || [];
            var labels = readiness.map((_, i) => 'R' + (i + 1));
            return {
                readinessChart: {
                    labels: labels,
                    datasets: [
                        { data: readiness },
                        { data: ds.audienceHistory || [] },
                        { data: ds.bodyHistory || [] },
                        { data: ds.deliveryHistory || [] }
                    ]
                }
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.readiness < 40) return window.mySimulation.t('hint_low');
            if (results.audience < 45) return window.mySimulation.t('hint_open');
            if (results.body < 45) return window.mySimulation.t('hint_body');
            if (results.delivery < 45) return window.mySimulation.t('hint_delivery');
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.roundLabelKey', label: 'Round', i18nKey: 'col_round',
                  formatter: function(v) { return v ? window.mySimulation.t(v) : '\u2014'; } },
                { key: 'results.audience',   label: 'Audience',  i18nKey: 'col_audience' },
                { key: 'results.body',       label: 'Body',      i18nKey: 'col_body' },
                { key: 'results.delivery',   label: 'Delivery',  i18nKey: 'col_delivery' },
                { key: 'results.readiness',  label: 'Readiness', i18nKey: 'col_readiness' }
            ];
        }

        getPresets() { return null; }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var ds = window.mySimulation && window.mySimulation.state ? window.mySimulation.state.domainState : null;
            var finalReadiness = ds ? ds.readiness : 0;
            var finalAudience = ds ? ds.audienceImpression : 0;
            var finalBody = ds ? ds.physiologicalControl : 0;
            var finalDelivery = ds ? ds.deliveryQuality : 0;

            var t = function(k) { return window.mySimulation.t(k); };
            var performance = 'beginner';
            if (finalReadiness >= 60) performance = 'solid';
            if (finalReadiness >= 75) performance = 'strong';
            if (finalReadiness >= 88) performance = 'stageready';

            var insights = [];
            insights.push(t(finalAudience >= 70 ? 'insight_open_good' : 'insight_open_weak'));
            insights.push(t(finalBody >= 70 ? 'insight_body_good' : 'insight_body_weak'));
            insights.push(t(finalDelivery >= 70 ? 'insight_delivery_good' : 'insight_delivery_weak'));
            insights.push(t('insight_transparency'));

            var overall = Math.max(0, Math.min(100, Math.round(finalReadiness)));
            return {
                finalReadiness: finalReadiness,
                audience: Math.round(finalAudience),
                body: Math.round(finalBody),
                delivery: Math.round(finalDelivery),
                performance: performance,
                performanceKey: performance,
                performanceLabel: t('perf_' + performance),
                composite: overall,
                overallScore: overall,
                totalScore: overall,
                score: overall,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var t = function(k) { return window.mySimulation.t(k); };
            var esc = function(x) {
                return String(x).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
            };
            var rows = [
                [t('audience_label'), (s.audience != null ? s.audience : 0) + ' / 100'],
                [t('body_label'), (s.body != null ? s.body : 0) + ' / 100'],
                [t('delivery_label'), (s.delivery != null ? s.delivery : 0) + ' / 100']
            ];
            var html = '<h3>' + esc(t('done_heading')) + '</h3>';
            html += '<div class="nerves-sim-debrief-score">' + esc((s.overallScore != null ? s.overallScore : 0) + '/100') + '</div>';
            html += '<p class="nerves-sim-debrief-verdict">' + esc(s.performanceLabel || '') + '</p>';
            html += '<table class="nerves-sim-debrief-table"><tbody>';
            rows.forEach(function(r) {
                html += '<tr><th scope="row">' + esc(r[0]) + '</th><td>' + esc(r[1]) + '</td></tr>';
            });
            html += '</tbody></table>';
            var ins = s.insights || [];
            if (ins.length) {
                html += '<h4>' + esc(t('done_insights')) + '</h4><ul>';
                ins.forEach(function(i) { html += '<li>' + esc(i) + '</li>'; });
                html += '</ul>';
            }
            var mount = document.getElementById('nervesDebrief');
            if (mount) { mount.innerHTML = html; mount.style.display = 'block'; }
            return html;
        }

